mapper.select:
SELECT form.* FROM wf_form_definition form WHERE form.tenant_id = #{tenantId} AND form.form_id = #{formId}
    AND form.is_latest = 0 AND form.version < #{keepFrom}
    AND NOT EXISTS (SELECT 1 FROM wf_process_instance instance
        JOIN wf_process_definition definition ON definition.tenant_id = instance.tenant_id AND definition.definition_id = instance.definition_id
        WHERE instance.tenant_id = #{tenantId} AND definition.form_id = #{formId} AND instance.form_version = form.version)
    ORDER BY form.version LIMIT 500
